CREATE OR ALTER PROCEDURE Sales.PlaceOrder
    @CustomerId INT,
    @Total      DECIMAL(12,2),
    @OrderId    INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        INSERT INTO Sales.Orders (CustomerId, Total) VALUES (@CustomerId, @Total);
        SET @OrderId = SCOPE_IDENTITY();
        COMMIT;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH;
END;
GO
DECLARE @id INT;
EXEC Sales.PlaceOrder @CustomerId = 7, @Total = 99.50, @OrderId = @id OUTPUT;

CREATE TRIGGER trg_BlockTableDrops
ON DATABASE
FOR DROP_TABLE
AS
BEGIN
    RAISERROR ('Tables cannot be dropped directly. Use the deployment pipeline.', 16, 1);
    ROLLBACK;
END;
